import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 Din,
    .param .u32 Hin,
    .param .u32 Win,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 K
)
{
    .reg .pred %p_exit, %p_has_bias, %p;

    .reg .u32 %rN, %rCin, %rCout, %rDin, %rHin, %rWin, %rDout, %rHout, %rWout, %rK;
    .reg .u32 %rBlock, %rBD, %rThread, %rTid;
    .reg .u32 %rTotal, %rTmp;

    .reg .u32 %rOx, %rOy, %rOz, %rO, %rNidx;

    .reg .u32 %rCidx, %rKz, %rKy, %rKx;

    .reg .s32 %rIz, %rIy, %rIx;

    .reg .u32 %rIdxX, %rIdxW, %rIdxY;

    .reg .f32 %fAcc, %fX, %fW;

    .reg .u64 %rdX, %rdW, %rdB, %rdY;
    .reg .u64 %rdOff, %rdAddr;

    // load params
    ld.param.u64 %rdX, [x_ptr];
    ld.param.u64 %rdW, [w_ptr];
    ld.param.u64 %rdB, [b_ptr];
    ld.param.u64 %rdY, [y_ptr];
    ld.param.u32 %rN, [N];
    ld.param.u32 %rCin, [Cin];
    ld.param.u32 %rCout, [Cout];
    ld.param.u32 %rDin, [Din];
    ld.param.u32 %rHin, [Hin];
    ld.param.u32 %rWin, [Win];
    ld.param.u32 %rDout, [Dout];
    ld.param.u32 %rHout, [Hout];
    ld.param.u32 %rWout, [Wout];
    ld.param.u32 %rK, [K];

    // Compute global thread id
    mov.u32 %rBlock, %ctaid.x;
    mov.u32 %rBD, %ntid.x;
    mov.u32 %rThread, %tid.x;
    mad.lo.s32 %rTid, %rBlock, %rBD, %rThread;

    // total = N*Cout*Dout*Hout*Wout
    mul.lo.u32 %rTotal, %rN, %rCout;
    mul.lo.u32 %rTotal, %rTotal, %rDout;
    mul.lo.u32 %rTotal, %rTotal, %rHout;
    mul.lo.u32 %rTotal, %rTotal, %rWout;

    setp.ge.u32 %p_exit, %rTid, %rTotal;
    @%p_exit ret;

    // Decompose indices
    rem.u32 %rOx, %rTid, %rWout;
    div.u32 %rTmp, %rTid, %rWout;

    rem.u32 %rOy, %rTmp, %rHout;
    div.u32 %rTmp, %rTmp, %rHout;

    rem.u32 %rOz, %rTmp, %rDout;
    div.u32 %rTmp, %rTmp, %rDout;

    rem.u32 %rO,  %rTmp, %rCout;
    div.u32 %rNidx, %rTmp, %rCout;

    // Initialize accumulator with bias if present
    setp.ne.u64 %p_has_bias, %rdB, 0;
    mov.f32 %fAcc, 0f00000000;
    @%p_has_bias mul.wide.u32 %rdOff, %rO, 4;
    @%p_has_bias add.u64 %rdAddr, %rdB, %rdOff;
    @%p_has_bias ld.global.f32 %fAcc, [%rdAddr];

    // c loop
    mov.u32 %rCidx, 0;

L_c_loop:
    setp.ge.u32 %p, %rCidx, %rCin;
    @%p bra L_c_done;

    // kz loop
    mov.u32 %rKz, 0;
L_kz_loop:
    setp.ge.u32 %p, %rKz, %rK;
    @%p bra L_kz_done;

    // iz = oz - kz
     sub.s32 %rIz, %rOz, %rKz;
    // bounds check 0 <= iz < Din
    setp.lt.s32 %p, %rIz, 0;
    @%p bra L_kz_continue;
    setp.ge.s32 %p, %rIz, %rDin;
    @%p bra L_kz_continue;

    // ky loop
    mov.u32 %rKy, 0;
L_ky_loop:
    setp.ge.u32 %p, %rKy, %rK;
    @%p bra L_ky_done;

    // iy = oy - ky
     sub.s32 %rIy, %rOy, %rKy;
    setp.lt.s32 %p, %rIy, 0;
    @%p bra L_ky_continue;
    setp.ge.s32 %p, %rIy, %rHin;
    @%p bra L_ky_continue;

    // kx loop
    mov.u32 %rKx, 0;
L_kx_loop:
    setp.ge.u32 %p, %rKx, %rK;
    @%p bra L_kx_done;

    // ix = ox - kx
     sub.s32 %rIx, %rOx, %rKx;
    setp.lt.s32 %p, %rIx, 0;
    @%p bra L_kx_continue;
    setp.ge.s32 %p, %rIx, %rWin;
    @%p bra L_kx_continue;

    // Load x[n,c,iz,iy,ix]
    // idxX = ((((n*Cin)+c)*Din + iz)*Hin + iy)*Win + ix
    mul.lo.u32 %rIdxX, %rNidx, %rCin;
    add.u32    %rIdxX, %rIdxX, %rCidx;
    mul.lo.u32 %rIdxX, %rIdxX, %rDin;
    add.u32    %rIdxX, %rIdxX, %rIz;
    mul.lo.u32 %rIdxX, %rIdxX, %rHin;
    add.u32    %rIdxX, %rIdxX, %rIy;
    mul.lo.u32 %rIdxX, %rIdxX, %rWin;
    add.u32    %rIdxX, %rIdxX, %rIx;
    mul.wide.u32 %rdOff, %rIdxX, 4;
    add.u64 %rdAddr, %rdX, %rdOff;
    ld.global.f32 %fX, [%rdAddr];

    // Load w[c,o,kz,ky,kx] with shape (Cin,Cout,K,K,K)
    mul.lo.u32 %rIdxW, %rCidx, %rCout;
    add.u32    %rIdxW, %rIdxW, %rO;
    mul.lo.u32 %rIdxW, %rIdxW, %rK;
    add.u32    %rIdxW, %rIdxW, %rKz;
    mul.lo.u32 %rIdxW, %rIdxW, %rK;
    add.u32    %rIdxW, %rIdxW, %rKy;
    mul.lo.u32 %rIdxW, %rIdxW, %rK;
    add.u32    %rIdxW, %rIdxW, %rKx;
    mul.wide.u32 %rdOff, %rIdxW, 4;
    add.u64 %rdAddr, %rdW, %rdOff;
    ld.global.f32 %fW, [%rdAddr];

    // fAcc += fX * fW
    fma.rn.f32 %fAcc, %fX, %fW, %fAcc;

L_kx_continue:
    add.u32 %rKx, %rKx, 1;
    bra L_kx_loop;

L_kx_done:

L_ky_continue:
    add.u32 %rKy, %rKy, 1;
    bra L_ky_loop;

L_ky_done:

L_kz_continue:
    add.u32 %rKz, %rKz, 1;
    bra L_kz_loop;

L_kz_done:
    // next c
    add.u32 %rCidx, %rCidx, 1;
    bra L_c_loop;

L_c_done:

    // Store y: idxY = ((((n*Cout)+o)*Dout + oz)*Hout + oy)*Wout + ox
    mul.lo.u32 %rIdxY, %rNidx, %rCout;
    add.u32    %rIdxY, %rIdxY, %rO;
    mul.lo.u32 %rIdxY, %rIdxY, %rDout;
    add.u32    %rIdxY, %rIdxY, %rOz;
    mul.lo.u32 %rIdxY, %rIdxY, %rHout;
    add.u32    %rIdxY, %rIdxY, %rOy;
    mul.lo.u32 %rIdxY, %rIdxY, %rWout;
    add.u32    %rIdxY, %rIdxY, %rOx;
    mul.wide.u32 %rdOff, %rIdxY, 4;
    add.u64 %rdAddr, %rdY, %rdOff;
    st.global.f32 [%rdAddr], %fAcc;

    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution with square input and square kernel using a single PTX kernel.
    Matches the reference constructor and parameters exactly.
    Only stride=1, padding=0, output_padding=0, groups=1 are supported at runtime.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, (tuple, list)):
            assert len(kernel_size) == 3 and kernel_size[0] == kernel_size[1] == kernel_size[2], "Only cubic kernels are supported"
            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        if stride != 1 or padding != 0 or output_padding != 0 or groups != 1:
            raise NotImplementedError("This implementation supports only stride=1, padding=0, output_padding=0, groups=1.")
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(k)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.groups = int(groups)

        # Weight layout matches nn.ConvTranspose3d: (in_channels, out_channels // groups, kD, kH, kW)
        w_shape = (self.in_channels, self.out_channels // self.groups, self.kernel_size, self.kernel_size, self.kernel_size)
        self.weight = nn.Parameter(torch.empty(w_shape, dtype=torch.float32))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels, dtype=torch.float32))
        else:
            self.bias = None

        # Initialize like PyTorch's ConvTranspose3d
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.dim() == 5, "Input must be NCDHW"
        N, Cin, Din, Hin, Win = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"
        assert self.groups == 1, "Only groups=1 supported"
        assert self.stride == 1 and self.padding == 0 and self.output_padding == 0, "Only stride=1, padding=0, output_padding=0 supported"
        K = self.kernel_size
        Cout = self.out_channels
        Dout = Din + K - 1
        Hout = Hin + K - 1
        Wout = Win + K - 1

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        # Kernel launch configuration
        total = N * Cout * Dout * Hout * Wout
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        module = _get_ptx_module()
        func_name = "the_entry_name"

        bias_arg = self.bias if self.bias is not None else u64(0)

        module.launch(
            func_name,
            grid=(int(grid_x), 1, 1),
            block=(int(block_x), 1, 1),
            arguments=[
                x,                              # x_ptr
                self.weight,                    # w_ptr
                bias_arg,                       # b_ptr (0 when no bias)
                y,                              # y_ptr
                i32(int(N)),                    # N
                i32(int(Cin)),                  # Cin
                i32(int(Cout)),                 # Cout
                i32(int(Din)),                  # Din
                i32(int(Hin)),                  # Hin
                i32(int(Win)),                  # Win
                i32(int(Dout)),                 # Dout
                i32(int(Hout)),                 # Hout
                i32(int(Wout)),                 # Wout
                i32(int(K)),                    # K
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

